@Composable private fun MapCanvas(active:String?,click:(String)->Unit){val rs=listOf("Marmara","Ege","Karadeniz","İç Anadolu","Akdeniz","Doğu Anadolu","Güneydoğu Anadolu");Canvas(Modifier.fillMaxWidth().height(190.dp).clip(RoundedCornerShape(18.dp)).background(Color(0xFF0A392D))){val w=size.width;val h=size.height;val path=Path().apply{moveTo(w*.06f,h*.45f);lineTo(w*.16f,h*.29f);lineTo(w*.30f,h*.34f);lineTo(w*.43f,h*.25f);lineTo(w*.60f,h*.27f);lineTo(w*.76f,h*.35f);lineTo(w*.93f,h*.52f);lineTo(w*.82f,h*.67f);lineTo(w*.70f,h*.76f);lineTo(w*.54f,h*.72f);lineTo(w*.42f,h*.83f);lineTo(w*.27f,h*.69f);lineTo(w*.14f,h*.65f);close()};drawPath(path,Color(0xFF2C7A59));drawPath(path,Color(0xFF8AD8AF),style=Stroke(3f));rs.forEachIndexed{i,r->drawCircle(if(active==r)Gold else Mint,if(active==r)13f else 9f,Offset(w*(.20f+i*.105f),h*(.44f+(i%2)*.10f)))};};Row(Modifier.horizontalScroll(rememberScrollState()).padding(top=6.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){rs.forEach{Text(it,color=if(active==it)Gold else Color.White.copy(.75f),fontSize=9.sp,fontWeight=FontWeight.Bold,modifier=Modifier.clickable{click(it)})}}}

