@Composable private fun ProfileV3(p:SharedPreferences){val s=p.getInt("solved",0);val c=p.getInt("correct",0);val w=p.getInt("wrong",0);val xp=p.getInt("xp",0);val streak=p.getInt("streak",0);val wins=p.getInt("wins",0);val a=if(s==0)0 else(c*100f/s).roundToInt();val level=1+xp/500;LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(18.dp,20.dp,18.dp,30.dp),verticalArrangement=Arrangement.spacedBy(11.dp)){item{Text("Profil",color=Deep,fontSize=30.sp,fontWeight=FontWeight.Black);Text("Coğrafya yolculuğun",color=Green,fontWeight=FontWeight.Bold)};item{CardV(Green,true){Row(verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(60.dp).background(Green,CircleShape),Alignment.Center){Text("🧭",fontSize=30.sp)};Spacer(Modifier.width(12.dp));Column{Text("Gezgin",color=Color.White,fontSize=21.sp,fontWeight=FontWeight.Black);Text("Seviye $level • $xp XP",color=Mint)}};Spacer(Modifier.height(12.dp));LinearProgressIndicator({(xp%500)/500f},Modifier.fillMaxWidth().height(7.dp),color=Green,trackColor=Color.White.copy(.15f))}};item{Stat("🎯","Doğruluk","%$a",Green)};item{Stat("📝","Çözülen","$s soru",Green)};item{Stat("❌","Yanlış","$w soru",Red)};item{Stat("🔥","Seri","$streak gün",Gold)};item{Stat("⚔️","Arena galibiyeti","$wins",Gold)};item{CardV(){Text("🏅 Başarımlar",color=Deep,fontSize=19.sp,fontWeight=FontWeight.ExtraBold);listOf("🧭 İlk Adım" to(s>=1),"🎯 Keskin Nişancı" to(a>=80&&s>=20),"🔥 7 Gün" to(streak>=7),"🏆 Arena Galibi" to(wins>=1),"📚 100 Soru" to(s>=100)).forEach{(n,on)->Row(Modifier.padding(vertical=5.dp),verticalAlignment=Alignment.CenterVertically){Icon(if(on)Icons.Default.CheckCircle else Icons.Default.Star,null,tint=if(on)Green else Color.LightGray);Spacer(Modifier.width(7.dp));Text(n,color=if(on)Deep else Color.Gray,fontWeight=if(on)FontWeight.Bold else FontWeight.Normal)}}}}}}

@Composable private fun QuizV3(title:String,questions:List<Question>,mode:String,p:SharedPreferences,exit:()->Unit){var i by remember{mutableIntStateOf(0)};var sel by remember{mutableStateOf<Int?>(null)};var answered by remember{mutableStateOf(false)};var correct by remember{mutableIntStateOf(0)};var wrong by remember{mutableIntStateOf(0)};var done by remember{mutableStateOf(false)};if(done){ResultV3(title,correct,wrong,questions.size,p,mode,exit){i=0;sel=null;answered=false;correct=0;wrong=0;done=false};return};val q=questions[i];Column(Modifier.fillMaxSize().background(Bg)){Row(Modifier.fillMaxWidth().padding(12.dp),verticalAlignment=Alignment.CenterVertically){IconButton(exit){Icon(Icons.Default.ArrowBack,"Çık")};Column(Modifier.weight(1f)){Text(title,color=Deep,fontWeight=FontWeight.ExtraBold);Text("Soru ${i+1}/${questions.size} • ${q.topic}",color=Green,fontSize=11.sp,fontWeight=FontWeight.Bold)}};LinearProgressIndicator({(i+1f)/questions.size},Modifier.fillMaxWidth().height(5.dp),color=Green,trackColor=Color(0xFFE0E8E4));LazyColumn(Modifier.weight(1f),contentPadding=PaddingValues(18.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{CardV(){Text(q.topic.uppercase(),color=Green,fontSize=10.sp,fontWeight=FontWeight.Black);Spacer(Modifier.height(6.dp));Text(q.text,color=Deep,fontSize=20.sp,fontWeight=FontWeight.ExtraBold)}};itemsIndexed(q.options){n,opt->val selected=sel==n;val good=n==q.correctIndex;val bc by animateColorAsState(when{!answered&&selected->Green;answered&&good->Green;answered&&selected->!good->Red;else->Color(0xFFE1E9E5)},label="answer");val bg=when{answered&&good->Soft;answered&&selected&&!good->Color(0xFFFFE9E9);selected->Color(0xFFEAF8F1);else->Color.White};Row(Modifier.fillMaxWidth().clip(RoundedCornerShape(17.dp)).background(bg).border(2.dp,bc,RoundedCornerShape(17.dp)).clickable(!answered){sel=n}.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(34.dp).background(bc.copy(.12f),CircleShape),Alignment.Center){Text(('A'.code+n).toChar().toString(),color=bc,fontWeight=FontWeight.Black)};Spacer(Modifier.width(10.dp));Text(opt,Modifier.weight(1f),color=Deep,fontWeight=if(selected||answered&&good)FontWeight.Bold else FontWeight.Normal);if(answered&&good)Icon(Icons.Default.CheckCircle,null,tint=Green)}};if(!answered)item{Button({if(sel!=null){answered=true;if(sel==q.correctIndex)correct++ else wrong++}},Modifier.fillMaxWidth().height(52.dp),shape=RoundedCornerShape(16.dp),colors=ButtonDefaults.buttonColors(Green),enabled=sel!=null){Text("Cevabı Kontrol Et",fontWeight=FontWeight.ExtraBold)}}else{item{CardV(if(sel==q.correctIndex)Green Red){Text(if(sel==q.correctIndex)"✓ DOĞRU":"✕ YANLIŞ",color=if(sel==q.correctIndex)Green Red,fontWeight=FontWeight.Black);Spacer(Modifier.height(5.dp));Text("Dikkat Köşesi",color=Deep,fontSize=18.sp,fontWeight=FontWeight.Black);Text(q.explanation,color=Color(0xFF596C63),fontSize=12.sp);Spacer(Modifier.height(6.dp));Text("Doğru cevap: ${('A'.code+q.correctIndex).toChar()}",color=Green,fontWeight=FontWeight.ExtraBold,fontSize=12.sp)}};item{Button({if(i==questions.lastIndex)done=true else{i++;sel=null;answered=false}},Modifier.fillMaxWidth().height(52.dp),shape=RoundedCornerShape(16.dp),colors=ButtonDefaults.buttonColors(Deep)){Text(if(i==questions.lastIndex)"Sonucu Gör" else "Sonraki Soru");Spacer(Modifier.width(5.dp));Icon(Icons.Default.ArrowForward,null)}}}}}}

@Composable private fun ResultV3(title:String,c:Int,w:Int,total:Int,p:SharedPreferences,mode:String,exit:()->Unit,retry:()->Unit){val oldS=p.getInt("solved",0);val oldC=p.getInt("correct",0);val oldW=p.getInt("wrong",0);val oldX=p.getInt("xp",0);val oldWins=p.getInt("wins",0);val gain=c*10+if(mode.contains("arena"))25 else 0;val ns=oldS+total;val nc=oldC+c;val nw=oldW+w;val win=oldWins+if(mode.contains("arena")&&c*2>=total)1 else 0;p.edit().putInt("solved",ns).putInt("correct",nc).putInt("wrong",nw).putInt("xp",oldX+gain).putInt("wins",win).apply();Column(Modifier.fillMaxSize().padding(22.dp),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Text("🏆",fontSize=60.sp);Text("Tur Tamamlandı!",color=Deep,fontSize=28.sp,fontWeight=FontWeight.Black);Text(title,color=Green,fontWeight=FontWeight.Bold);Spacer(Modifier.height(18.dp));Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){RP("$c","Doğru",Green);RP("$w","Yanlış",Red);RP("%${if(total==0)0 else(c*100f/total).roundToInt()}","Başarı",Gold)};Spacer(Modifier.height(18.dp));CardV(){Text("+$gain XP",color=Green,fontSize=22.sp,fontWeight=FontWeight.Black);Text("Toplam $ns soru • Genel doğruluk %${if(ns==0)0 else(nc*100f/ns).roundToInt()}",color=Color.Gray,fontSize=12.sp)};Spacer(Modifier.height(16.dp));Button(retry,Modifier.fillMaxWidth().height(52.dp),shape=RoundedCornerShape(16.dp),colors=ButtonDefaults.buttonColors(Green)){Icon(Icons.Default.Refresh,null);Spacer(Modifier.width(6.dp));Text("Tekrar Çöz")};TextButton(exit){Text("Ana menüye dön",color=Deep)}}}

